param([Parameter(Mandatory)][string]$Python,[string]$ProjectRoot=(Join-Path $PSScriptRoot '..'),[string]$BuildRoot='')
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot 'out/staging'};$BuildRoot=[IO.Path]::GetFullPath($BuildRoot)
Add-Type -Path (Join-Path $PSScriptRoot 'PrivateDesktop.cs')
$root=Join-Path $ProjectRoot ('artifacts/world-journal-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null;Set-Content "$root/.synthetic-world-journal-test" 'Synthetic data only.'
$desktop=$null;$service=$null;$locker=$null;$checks=0;$env:HIBERNATION_SESSION_KEY='world-journal-fixture';$env:TEMP="$BuildRoot/tmp";$env:TMP=$env:TEMP
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name,[int]$Seconds=20){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 30};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$a=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer world-journal-fixture'};TimeoutSec=12};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 35 -Compress))};Invoke-RestMethod @a}
function World{(Api '/api/capabilities').plugins.Where({$_.id-eq'habitat'})[0].current}
function Plugin($Name,$Arguments){$null=Api '/api/plugin/test' @{tool=$Name;args=$Arguments};Wait-For {$script:result=Api '/api/plugin/result';$script:result.state-in@('succeeded','failed')} $Name;return $script:result.result}
function Start-Backend{Remove-Item "$root/ready.json" -ErrorAction SilentlyContinue;$script:desktop=[PrivateDesktop]::new("$BuildRoot/hibernation-agent.exe","$root/config.json","$root/ready.json",$ProjectRoot);$script:service=$desktop.Child;Wait-For {if($service.HasExited){throw 'fixture exited'};Test-Path "$root/ready.json"} 'backend';$script:origin='http://127.0.0.1:'+((Get-Content "$root/ready.json" -Raw|ConvertFrom-Json).port)}
function Stop-Backend{$null=Api '/api/shutdown' @{};$exited=$service.WaitForExit(10000);Check ($exited-and$service.ExitCode-eq0) ("recovered backend exits cleanly (exit=$($service.ExitCode), exited=$exited)");$desktop.Dispose();$script:desktop=$null}
function Inspect($Mode='inspect'){$value=& "$BuildRoot/Hibernation_WorldArchiveFixture.exe" $Mode $root;if($LASTEXITCODE-ne0){throw 'world archive fixture failed'};$value|ConvertFrom-Json}
try{
 $cfg=Get-Content "$ProjectRoot/config/example.json" -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot="$root/data";$cfg.characterRoot="$ProjectRoot/character";$cfg.uiRoot="$ProjectRoot/ui";$cfg.pluginRoot="$BuildRoot/plugins";$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.profiles=@($cfg.profiles[0]);$cfg.plugins=@{widget=@{enabled=$true;roam=$false};habitat=@{enabled=$true;autoSpawn=$false;autoInteract=$false;wakeOnAction=$false}};$cfg|ConvertTo-Json -Depth 35|Set-Content "$root/config.json" -Encoding utf8
 Start-Backend;Wait-For {(World).desktop} 'world';$placed=Plugin 'habitat.place' @{kind='berry'};Check $placed.ok 'food appears on the private desktop';$item=$placed.result.objects[0];$null=Api '/api/surfaces/show' @{id='habitat'};Check ((Inspect).checkpoint_objects-eq1) 'pre-action checkpoint contains the uneaten object'
 $accepted=Plugin 'habitat.act' @{id=$item.id;action='eat'};Check $accepted.ok 'actual action begins';Wait-For {(World).pending.phase-eq'acting'} 'arrival and eating animation'
 $locker=Start-Process $Python -ArgumentList ('"'+$ProjectRoot+'/tests/HoldJournal.py" "'+$root+'"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/lock.log" -RedirectStandardError "$root/lock-error.log";Wait-For {if($locker.HasExited){throw 'journal lock failed'};Test-Path "$root/lock-ready"} 'held journal'
 Wait-For {(World).objects.Count-eq0-and(World).last_actions.Count-eq1} 'action completes with blocked index';Wait-For {(Api '/api/chat').health-eq'journal_unavailable'} 'index failure reported';$held=Inspect;Check ($held.completed-eq1-and$held.pending-eq1-and$held.experiences-eq1) 'actual experience and pending index entry persist together';Check ($held.checkpoint_objects-eq0) 'completed-world checkpoint is atomic with experience';Check ((Api '/api/events' @{channel='agent.world.habitat'}).events.Count-eq0) 'blocked index has no prematurely successful receipt'
 Stop-Process -Id $service.Id;$service.WaitForExit(5000)|Out-Null;$desktop.Dispose();$desktop=$null;Set-Content "$root/release-lock" 'release';Check ($locker.WaitForExit(5000)-and$locker.ExitCode-eq0) 'synthetic lock is released after abrupt process loss'
 Start-Backend;Wait-For {(Api '/api/events' @{channel='agent.world.habitat'}).events.Count-eq1} 'pending entry repairs after restart';$events=Api '/api/events' @{channel='agent.world.habitat'};$source=$events.events[0].event_id;Check ((World).objects.Count-eq0-and(World).last_actions.Count-eq1) 'crash does not resurrect consumed food or replay the action';$repaired=Inspect;Check ($repaired.pending-eq0-and$repaired.completed-eq1-and$repaired.experiences-eq1) 'repaired index does not create a second experience';Check (!(($events|ConvertTo-Json -Depth 15).Contains('浆果'))-and!(($events|ConvertTo-Json -Depth 15).Contains('"text"'))) 'recovered index remains metadata only';Stop-Backend
 $injected=Inspect 'mark-pending';Check ($injected.pending-eq1) 'equivalent crash state after index publication is injected';Start-Backend;Wait-For {(Inspect).pending-eq0} 'duplicate index acknowledged';$again=Api '/api/events' @{channel='agent.world.habitat'};Check ($again.events.Count-eq1-and$again.events[0].event_id-eq$source) 'existing index identity is acknowledged without duplicate publication';Check ((Inspect).experiences-eq1-and(Api '/api/chat').health-eq'ok') 'duplicate acknowledgement restores normal health';Stop-Backend
 @{completed=$true;checks=$checks;root=$root;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content "$root/acceptance.json";Write-Output "World journal recovery passed: $checks checks. Evidence: $root"
}finally{Set-Content "$root/release-lock" 'release';if($locker){$locker.Refresh();if(!$locker.HasExited){$locker.WaitForExit(2000)|Out-Null;if(!$locker.HasExited){Stop-Process -Id $locker.Id}}};if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($desktop){$desktop.Dispose()}}
